"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["83852"],{65935(e){e.exports=JSON.parse('{"id":"FIN-1469","slug":"security-interest","term":"Security Interest","also_known_as":[],"difficulty":"Advanced","definition":"A security interest is a legal right granted by a borrower to a lender over specific assets, allowing the lender to take and sell those assets if the borrower fails to repay.","explanation":["A security interest turns an unsecured loan into a secured one. If the borrower defaults, the lender with the security interest can enforce it, typically by taking possession of the assets and selling them to recover the debt, ahead of unsecured creditors.","Security interests can cover many types of assets, including property, equipment, inventory, receivables, bank accounts, shares and intellectual property. A mortgage is a security interest over property.","For example, a company borrows 5,000,000 from a bank and grants a security interest over its machinery and inventory. If it defaults, the bank can sell those assets to recover the loan.","To be effective against other creditors, security interests usually must be registered or perfected under local law. In the United States, this is often done by filing a financing statement under the Uniform Commercial Code; in the United Kingdom, company charges are registered at Companies House. Priority among creditors often depends on the order in which security interests were registered."],"note":"","total":1725,"prev":{"slug":"securitization","term":"Securitization"},"next":{"slug":"security-token","term":"Security Token"}}')}}]);